<script setup lang="ts">
// SiteHeader: reusable Avada header (full = mega+phone, short = home).
// The current nav item is highlighted by matching the active route.
import { useRoute } from 'vue-router'

withDefaults(defineProps<{ variant?: 'full' | 'short' }>(), { variant: 'full' })
const route = useRoute()

function highlightCurrent() {
  if (typeof window === 'undefined') return
  const path = route.path.split('?')[0].replace(/\/+$/, '')
  const cur = path === '' ? '/' : path
  document.querySelectorAll('.awb-menu__main-a[href]').forEach((a) => {
    // Only highlight items in the site navigation menus; leave the cart/search
    // widget menus (which Avada marks active itself) untouched.
    const scope = a.closest('#menu-vegan-store-main-menu, #menu-categories-mega-menu')
    if (!scope) return
    const href = a.getAttribute('href')
    if (!href || href.startsWith('http') || href === '#') return
    let h = href.split('?')[0].replace(/\/+$/, '')
    if (h === '') h = '/'
    const isMatch = cur === h
    const li = a.closest('li')
    if (li) {
      if (isMatch) {
        li.classList.add('current-menu-item', 'current_page_item', 'awb-menu__main-li_active')
        a.setAttribute('aria-current', 'page')
      } else {
        li.classList.remove('current-menu-item', 'current_page_item', 'awb-menu__main-li_active')
        a.removeAttribute('aria-current')
      }
    }
  })
}

onMounted(highlightCurrent)
watch(() => route.path, highlightCurrent)
</script>

